using System;using System.Collections.Generic;
namespace LordranEnemy {public static class StatusSusceptibility {
 public static bool[] Flags(byte[] b){if(b==null||b.Length<0x25A)throw new Exception("Effect parameters unavailable.");return new[]{(b[0x163]&4)!=0,(b[0x163]&8)!=0,(b[0x163]&16)!=0,(b[0x163]&32)!=0,(b[0x259]&8)!=0,(b[0x15F]&128)!=0,(b[0x160]&1)!=0};}
 public static string State(EnemySnapshot s,int i){if(s==null||i<0||i>=7||s.StatusBlocked==null||i>=s.StatusBlocked.Length)return "Unknown";if(s.StatusBlocked[i])return "Immune";if(s.BaseStatus==null||s.Thresholds==null||i>=s.BaseStatus.Length||i>=s.Thresholds.Length||s.BaseStatus[i]>=999||s.Thresholds[i]<=0)return "Unknown";return "Yes";}
 public static bool[] Read(long actor,Func<long,int,byte[]> read){long effects=EnemyReader.Pointer(read,actor+0x178);if(EnemyReader.Pointer(read,effects+0x10)!=actor)throw new Exception("Effect owner mismatch.");long first=BitConverter.ToInt64(read(effects+8,8),0),node=first;var seen=new HashSet<long>();var blocked=new bool[7];var entries=new Dictionary<long,byte[]>();while(node!=0){if(node<0x10000||node>0x7FFFFFFFFFFF||seen.Count>=512||!seen.Add(node))throw new Exception("Effect list invalid.");byte[] entry=read(node,0x40);entries.Add(node,entry);long param=BitConverter.ToInt64(entry,0),next=BitConverter.ToInt64(entry,0x30);int id=BitConverter.ToInt32(entry,8);if(param<0x10000||param>0x7FFFFFFFFFFF||id<0)throw new Exception("Effect parameter invalid.");bool[] flags=Flags(read(param,0x25A));for(int i=0;i<7;i++)blocked[i]|=flags[i];if(!read(node,0x40).AsSpanEqual(entry))throw new Exception("Effect changed during reading.");node=next;}
 foreach(var entry in entries)if(!read(entry.Key,0x40).AsSpanEqual(entry.Value))throw new Exception("Effect list changed during reading.");
 if(EnemyReader.Pointer(read,actor+0x178)!=effects||EnemyReader.Pointer(read,effects+0x10)!=actor||BitConverter.ToInt64(read(effects+8,8),0)!=first)throw new Exception("Effects changed during reading.");return blocked;}
}}
